// Generated 3D models, created by name. Written by Milq whenever it generates
// a model: do not edit this file, and never import 'three/addons/' anywhere
// else.
//
//   // src/main.js, once, before the first scene starts:
//   await preloadModels(['red-car', 'runner']);
//
//   // anywhere after that:
//   const car = createModel('red-car', { length: 4 });
//   car.position.set(0, 0, -6);
//   this.root.add(car);
//
//   // an animated character plays a clip, driven from the scene's update(dt):
//   const runner = createModel('runner', { height: 1.8, animation: 'running' });
//   runner.userData.play('walking');                // switch, with a short blend
//   runner.userData.play('running', { speed: 1.4 }); // its pace
//   runner.userData.play('regular-jump', { once: true }); // once, holding its last frame
//   runner.userData.clipDuration('regular-jump');   // its length in seconds
//   runner.userData.play(null);                     // stop
//   updateModels(dt);                               // once per frame, in update(dt)
//
// Every model comes back normalised: scaled to the size asked for, with its
// lowest point on y = 0 and centred over the origin, so position.y = 0 stands
// it on the ground. Size it with ONE of height (y), width (x), length (z) or
// size (its longest side), in world units; the default is height 1. A model
// keeps its own texture and ignores color; only one that came back without a
// texture is painted the color given, light grey by default. Copies share
// their geometry and materials, so many cost little more than one.
//
// createModel always returns at once. A model that was not preloaded appears
// as soon as it has loaded; one that cannot be loaded is a plain box of the
// requested size, with the reason in the console.

import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { clone as cloneSkinned } from 'three/addons/utils/SkeletonUtils.js';

const loader = new GLTFLoader();
const sources = new Map();
const materials = new Map();
const mixers = new Set();

// A clip's play name. Meshy names a clip "Armature|<key>|baselayer": its
// rig's own are running and walking ("walking_man"), any other goes by its
// key ("Regular_Jump" plays as "regular-jump"). A clip Milq added already
// carries its play name.
function clipName(clip) {
  const parts = clip.name.split('|');
  if (parts.length !== 3 || parts[0] !== 'Armature') return clip.name;
  const key = parts[1].toLowerCase();
  if (key === 'running') return 'running';
  if (key.startsWith('walking')) return 'walking';
  return key.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

function source(name) {
  let entry = sources.get(name);
  if (!entry) {
    const url = `assets/models/${name}.glb`;
    entry = { scene: null, failed: false, clips: new Map(), box: null, waiting: [] };
    entry.ready = loader.loadAsync(url).then(
      async (gltf) => {
        for (const clip of gltf.animations) entry.clips.set(clipName(clip), clip);
        if (gltf.animations.length) {
          // An animated character's walking clip is a second file on the
          // same skeleton; without it the character only runs.
          try {
            const walking = await loader.loadAsync(`assets/models/${name}.walking.glb`);
            for (const clip of walking.animations) {
              if (!entry.clips.has(clipName(clip))) entry.clips.set(clipName(clip), clip);
            }
          } catch (error) {}
        }
        entry.box = restBox(gltf.scene);
        entry.scene = gltf.scene;
      },
      (error) => {
        entry.failed = true;
        console.error(`models.js: could not load "${name}" from ${url}: ${error && error.message ? error.message : error}`);
      }
    ).then(() => {
      for (const fill of entry.waiting.splice(0)) fill();
    });
    sources.set(name, entry);
  }
  return entry;
}

// The model's bounds as it is drawn at rest: a skinned character is placed
// by its bones, not by the transform of the mesh they deform.
function restBox(scene) {
  scene.updateMatrixWorld(true);
  return new THREE.Box3().setFromObject(scene, true);
}

/// Loads the named models, so createModel returns them complete. Never rejects.
export function preloadModels(names) {
  return Promise.all(names.map((name) => source(name).ready)).then(() => undefined);
}

/// A new copy of a generated model, normalised as described above. An
/// animated one plays options.animation (with options.speed) and answers
/// userData.play(name, { speed }) to switch; play(null) stops it.
export function createModel(name, options = {}) {
  const holder = new THREE.Group();
  holder.name = name;
  const entry = source(name);
  let mixer = null;
  let current = null;
  let wanted = options.animation ? { clip: options.animation, speed: options.speed ?? 1, once: false } : null;

  const start = () => {
    const clip = wanted && entry.clips.get(wanted.clip);
    if (wanted && !clip) {
      console.warn(`models.js: "${name}" has no "${wanted.clip}" animation (it has: ${[...entry.clips.keys()].join(', ') || 'none'})`);
    }
    const action = clip ? mixer.clipAction(clip) : null;
    if (action && action === current && !wanted.once) {
      action.timeScale = wanted.speed;
      return;
    }
    if (current && current !== action) current.fadeOut(0.2);
    if (action) {
      action.reset();
      action.timeScale = wanted.speed;
      // Once: played through a single time and held on its last frame.
      action.setLoop(wanted.once ? THREE.LoopOnce : THREE.LoopRepeat, wanted.once ? 1 : Infinity);
      action.clampWhenFinished = wanted.once;
      if (current && current !== action) action.fadeIn(0.2);
      action.play();
    }
    current = action;
  };

  holder.userData.play = (clip, { speed = 1, once = false } = {}) => {
    wanted = clip ? { clip, speed, once: Boolean(once) } : null;
    if (mixer) start();
  };

  // A clip's length in seconds (0 until the model has loaded, or for a clip
  // it does not have).
  holder.userData.clipDuration = (clip) => entry.clips.get(clip)?.duration ?? 0;

  const fill = () => {
    if (!entry.scene) {
      holder.add(standIn(options));
      return;
    }
    const model = fitted(entry, options);
    holder.add(model);
    if (entry.clips.size) {
      mixer = new THREE.AnimationMixer(model);
      mixers.add({ mixer, holder, seen: false });
      start();
    }
  };
  if (entry.scene || entry.failed) fill();
  else entry.waiting.push(fill);
  return holder;
}

/// Advances every animated model. Call once per frame from the scene's
/// update(dt); without it animated characters stand frozen.
export function updateModels(dt) {
  for (const animated of mixers) {
    if (inScene(animated.holder)) {
      animated.seen = true;
      animated.mixer.update(dt);
    } else if (animated.seen) {
      // Taken out of the scene (a restart clears it): nothing drives it again.
      mixers.delete(animated);
    }
  }
}

function inScene(object) {
  let node = object;
  while (node.parent) node = node.parent;
  return node.isScene === true;
}

function fitted(entry, options) {
  const model = entry.clips.size ? cloneSkinned(entry.scene) : entry.scene.clone(true);
  paint(model, options.color);
  const box = entry.box;
  const extent = box.getSize(new THREE.Vector3());
  const centre = box.getCenter(new THREE.Vector3());
  const [wanted, actual] =
    options.width ? [options.width, extent.x] :
    options.length ? [options.length, extent.z] :
    options.size ? [options.size, Math.max(extent.x, extent.y, extent.z)] :
    [options.height || 1, extent.y];
  const scale = actual > 0 ? wanted / actual : 1;
  model.scale.multiplyScalar(scale);
  model.position.set(-centre.x * scale, -box.min.y * scale, -centre.z * scale);
  return model;
}

// Every model gets a plain lit material. An untextured one is its colour:
// glTF's default material is fully metallic, which renders black without an
// environment map. A textured one keeps its texture, untinted: the rig's
// material is metallic too, and lit by its own texture as if glowing, which
// flattens it in a lit scene.
function paint(model, color) {
  model.traverse((object) => {
    if (!object.isMesh) return;
    const original = Array.isArray(object.material) ? object.material[0] : object.material;
    const map = original && original.map;
    object.material = plain(map ? undefined : color, map, original && original.side);
  });
}

function plain(color, map = null, side = THREE.FrontSide) {
  const key = `${color === undefined ? '' : color}|${map ? map.uuid : ''}|${side}`;
  let material = materials.get(key);
  if (!material) {
    material = new THREE.MeshStandardMaterial({
      color: color === undefined ? (map ? 0xffffff : 0xd9d9d9) : color,
      map,
      side,
      roughness: 0.8,
      metalness: 0
    });
    materials.set(key, material);
  }
  return material;
}

function standIn(options) {
  const side = options.height || options.width || options.length || options.size || 1;
  const box = new THREE.Mesh(new THREE.BoxGeometry(side, side, side), plain(options.color));
  box.position.y = side / 2;
  return box;
}
